CREATE TABLE IF NOT EXISTS mothers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), mother_code VARCHAR(50) UNIQUE NOT NULL, branch_id UUID NOT NULL REFERENCES branches(id), full_name_ar VARCHAR(255) NOT NULL, full_name_en VARCHAR(255), identity_number VARCHAR(100), birth_date DATE, death_date DATE, death_reason_id UUID REFERENCES lookups(id), marital_status_id UUID REFERENCES lookups(id), gender_id UUID REFERENCES lookups(id), occupation_id UUID REFERENCES lookups(id), nationality_id UUID REFERENCES lookups(id), health_status_id UUID REFERENCES lookups(id), is_guardian BOOLEAN DEFAULT FALSE, is_alive BOOLEAN DEFAULT TRUE, phone VARCHAR(50), address TEXT, notes TEXT, is_active BOOLEAN DEFAULT TRUE, is_deleted BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP); 
